package com.asistencia.attendance.domain;

import com.asistencia.shared.domain.InvalidInputException;
import java.time.Instant;
import java.util.UUID;

/**
 * A worker's request to mark.
 *
 * @param clientId   generated by the phone; makes retries of a queued mark idempotent
 * @param capturedAt device clock when the GPS fix was taken
 */
public record MarkAttempt(UUID clientId, long employeeId, MarkType type, LocationReading location, Instant capturedAt) {

    public MarkAttempt {
        if (clientId == null || type == null || location == null || capturedAt == null) {
            throw new InvalidInputException("Incomplete punch.");
        }
    }
}
